{
  "bloco_id": "F05-V02-B005",
  "subtitulo": "Análise de causa: mecanismo de falha, modo de falha e FMEA",
  "recorte": {
    "id": "F05",
    "foco": "Desempenho das equipes, acompanhamento de ações, análise de causa, aprendizagem e revisão das metas."
  },
  "sintese_tecnica": "Na análise de causa, convém distinguir mecanismo de falha de modo de falha. Mecanismo de falha é o fenômeno ou processo que atua sobre materiais, partes, estruturas, operações ou controles e leva à perda discreta, progressiva ou acelerada de resistência, funcionalidade ou reserva operacional. Modo de falha é a forma de manifestação da incapacidade de operar, podendo ocorrer de forma súbita ou pela progressão ou conjugação de mecanismos. Essa separação ajuda a não limitar a resposta apenas ao sintoma visível. Como ferramenta de apoio, o FMEA é apresentado, no contexto visível, para estruturar a análise por equipe multidisciplinar. No caso descrito para instalação de sistema BCS, aparecem recomendações de treinamento da equipe, preparo para substituição do coordenador quando necessário e, após domínio da ferramenta e conhecimento do sistema/processo analisado, uso de procedimento documentado para coleta de dados, preenchimento e análise. O formulário considera severidade, ocorrência e detecção; o produto dessas avaliações apoia a priorização de falhas potenciais. Esse princípio de priorização é tecnicamente transferível como combinação entre consequência, chance de ocorrência e capacidade de detecção antecipada, sem fixar escala única para FPSOs ou outros contextos.",
  "conceitos": [
    {
      "termo": "Mecanismo de falha",
      "definicao": "Fenômeno ou processo que atua nos materiais, partes, estruturas, meios, superfícies, interações, operações ou controles e causa perda discreta, progressiva ou acelerada de resistência, funcionalidade ou reserva de operacionalidade.",
      "observacoes": [
        "Pode interagir com outros mecanismos de falha."
      ]
    },
    {
      "termo": "Modo de falha",
      "definicao": "Forma de manifestação da incapacidade de operar.",
      "observacoes": [
        "Pode ocorrer de forma súbita.",
        "Pode resultar da progressão ou conjugação de vários mecanismos de falha."
      ]
    },
    {
      "termo": "FMEA",
      "definicao": "Ferramenta de apoio para estruturar a análise de modos e efeitos de falha por equipe multidisciplinar.",
      "observacoes": [
        "No material visível, aparece associada à identificação de causa raiz, recomendações e redução de falhas potenciais no contexto de instalação de sistema BCS."
      ]
    }
  ],
  "relacoes_importantes": [
    {
      "relacao": "Mecanismo de falha -> causa/processo",
      "implicacao": "Direciona a investigação para o fenômeno subjacente."
    },
    {
      "relacao": "Modo de falha -> manifestação",
      "implicacao": "Descreve como a incapacidade de operar aparece no sistema."
    },
    {
      "relacao": "Separar mecanismo e modo",
      "implicacao": "Reduz o risco de corrigir apenas a manifestação imediata do problema."
    },
    {
      "relacao": "Severidade + ocorrência + detecção",
      "implicacao": "Baseiam a priorização no FMEA, conforme o contexto apresentado."
    }
  ],
  "contexto_de_aplicacao_preservado": {
    "principal": "Instalação de sistema BCS nas empresas citadas no trecho de origem.",
    "condicoes": [
      "Treinamento da equipe multidisciplinar, coordenador e demais membros.",
      "Preparação para substituição do coordenador quando necessário.",
      "Uso posterior de procedimento documentado após domínio da ferramenta e conhecimento/experiência no sistema ou processo analisado."
    ],
    "cautelas": [
      "As recomendações visíveis são contextualizadas ao caso de instalação de BCS.",
      "O material não autoriza transformar esse arranjo específico em obrigação universal para qualquer ativo ou organização."
    ]
  },
  "limites_e_incertezas": [
    "Os trechos sustentam a distinção conceitual entre mecanismo de falha e modo de falha e o uso do FMEA no contexto descrito, mas não fixam uma escala única de pontuação aplicável a FPSOs em geral.",
    "A multiplicação das avaliações de severidade, ocorrência e detecção aparece no trecho do caso analisado; isso não deve ser convertido automaticamente em requisito universal fora do contexto apresentado.",
    "Os trechos visíveis não detalham critérios numéricos completos, faixas de classificação ou procedimento corporativo integral.",
    "Trechos correlatos sobre FMEA e definições regulatórias compõem um mesmo material de apoio e não devem ser tratados como estudos independentes."
  ],
  "pontos_para_ensino": [
    "Diferenciar causa/processo de manifestação é central em análise de falhas.",
    "Mecanismos podem atuar de forma progressiva ou acelerada e também interagir entre si.",
    "Modos de falha podem ser súbitos ou resultar da evolução de mecanismos.",
    "Em FMEA, a organização da análise por equipe multidisciplinar é parte relevante do processo.",
    "No contexto visível, treinamento e padronização documental aparecem como etapas para melhorar coleta de dados, preenchimento e análise."
  ],
  "evidencias": [
    {
      "trecho_id": "E3a62b13e285f3be8:0:693",
      "uso": "Definição de mecanismo de falha."
    },
    {
      "trecho_id": "E3a62b13e285f3be8:693:1388",
      "uso": "Definição de modo de falha."
    },
    {
      "trecho_id": "E64b983c0267551e7:695:1393",
      "uso": "Treinamento da equipe, conhecimento da ferramenta e substituição do coordenador no contexto de instalação de BCS."
    },
    {
      "trecho_id": "E64b983c0267551e7:1393:2091",
      "uso": "Procedimento documentado, coleta de dados, preenchimento e análise; avaliações de severidade, ocorrência e detecção."
    },
    {
      "trecho_id": "E64b983c0267551e7:2091:2219",
      "uso": "Produto das três avaliações para apoiar priorização."
    }
  ],
  "propostas": [
    {
      "relacao": "Integração entre distinção mecanismo/modo de falha e qualidade do registro de ações corretivas na rotina das equipes",
      "recorte_destino": "F05",
      "trechos": [
        "E3a62b13e285f3be8:0:693",
        "E3a62b13e285f3be8:693:1388",
        "E64b983c0267551e7:695:1393"
      ],
      "consultas": [
        "Como a separação explícita entre mecanismo e modo de falha altera a qualidade dos registros de causa e das ações corretivas pelas equipes?",
        "Há redução de retrabalho ou de recorrência quando os formulários distinguem fenômeno causador e forma de manifestação?"
      ]
    },
    {
      "relacao": "Efeito do treinamento e da substituição planejada do coordenador na consistência de aplicação do FMEA em serviços de instalação",
      "recorte_destino": "F05",
      "trechos": [
        "E64b983c0267551e7:695:1393",
        "E64b983c0267551e7:1393:2091"
      ],
      "consultas": [
        "A preparação de substitutos do coordenador preserva consistência de critérios e continuidade da análise em equipes multidisciplinares?",
        "Quais sinais operacionais indicam que a equipe já domina a ferramenta a ponto de migrar para procedimento documentado rotineiro?"
      ]
    }
  ]
}
